/*
 * A011735  A binary m-sequence: expansion of reciprocal of x^22 + x + 1 (mod
 *          2, shifted by 21 initial 0's).
 * https://oeis.org/A011735
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = a(n-1) ^ a(n-22) (mod 2) with initial values
 *            a(0)=a(1)=...=a(20)=0 and a(21)=1. This implements the binary
 *            m‑sequence generated by 1/(x^22 + x + 1) shifted by 21 initial
 *            zeros
 * Range:     u8 n <= 80, u16 n <= 80, u32 n <= 80, u64 n <= 80, u128 n <= 80,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

seq_t a(idx_t n)
{
    /* The first 21 terms are zero, the 22nd term (index 21) is 1. */
    if (n <= 20) return (seq_t)0;
    if (n == 21) return (seq_t)1;

    /* Ring buffer of the last 22 values.  Index 0 corresponds to
       a(i-22), index 21 to a(i-1) during the iteration for a(i). */
    seq_t buf[22] = {0};
    buf[21] = (seq_t)1;   /* a(21) */

    size_t head = 0;      /* points to a(i-22) in the current step */

    for (idx_t i = 22; i <= n; ++i) {
        /* a(i-1) is at (head+21)%22, a(i-22) is at head */
        seq_t val = buf[(head + 21) % 22] ^ buf[head];

        /* Store the newly computed value at the position of a(i-22),
           which becomes a(i) after the head is advanced. */
        buf[head] = val;

        /* Advance head to point to a(i-21) for the next iteration. */
        head = (head + 1) % 22;
    }

    /* After the loop, a(n) resides at (head+21)%22. */
    return buf[(head + 21) % 22];
}
